INSERT INTO BATTER_STATS (tp_id, season_id, games_played, plate_appearance, at_bats, hits, doubles, triples, home_runs, runs_batted_in, stolen_bases, walks, strikeouts, batting_average, on_base_pct, slugging_pct, ops) SELECT tp.tp_id, @season_id, 5, 18, 12, 6, 1, 0, 0, 6, 2, 6, 3, 0.5, 0.667, 0.583, 1.25 FROM TEAM_PLAYER tp JOIN PLAYER p ON tp.player_id = p.player_id JOIN TEAM t ON tp.team_id = t.team_id WHERE p.player_name = '김우빈' AND t.team_name = '상명대BUCKS' AND tp.season_id = @season_id AND NOT EXISTS (SELECT 1 FROM BATTER_STATS bs WHERE bs.tp_id = tp.tp_id AND bs.season_id = @season_id) LIMIT 1;
