INSERT INTO GAME (season_id, game_date, game_number, home_team, away_team, home_score, away_score, game_type) SELECT @season_id, CURDATE(), 801046, @team_24, @team_extra_0, 13, 14, 'REGULAR' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM GAME WHERE season_id = @season_id AND game_number = 801046);
INSERT INTO TEAM_PLAYER (team_id, player_id, season_id) SELECT @team_24, p.player_id, @season_id FROM PLAYER p WHERE p.player_name = '박한열' AND NOT EXISTS (SELECT 1 FROM TEAM_PLAYER tp2 WHERE tp2.team_id = @team_24 AND tp2.player_id = p.player_id AND tp2.season_id = @season_id) LIMIT 1;
INSERT INTO BATTER_STATS (tp_id, season_id) SELECT tp.tp_id, @season_id FROM TEAM_PLAYER tp JOIN PLAYER p ON tp.player_id = p.player_id WHERE p.player_name = '박한열' AND tp.team_id = @team_24 AND tp.season_id = @season_id AND NOT EXISTS (SELECT 1 FROM BATTER_STATS bs WHERE bs.tp_id = tp.tp_id AND bs.season_id = @season_id) LIMIT 1;
INSERT INTO BATTER_GAME_LOG (game_idx, team_side, team_idx, player_idx, batter_stat_id, player_name, player_position, at_bats, runs, hits, rbi, walks, strikeouts) SELECT @game_id, 'home', @team_24, (SELECT player_id FROM PLAYER WHERE player_name = '박한열' LIMIT 1), (SELECT bs.batter_stat_id FROM BATTER_STATS bs JOIN TEAM_PLAYER tp ON bs.tp_id = tp.tp_id JOIN PLAYER p ON tp.player_id = p.player_id WHERE p.player_name = '박한열' AND tp.team_id = @team_24 AND bs.season_id = @season_id LIMIT 1), '박한열', '투', 2, 3, 1, 0, NULL, NULL FROM DUAL WHERE @game_id IS NOT NULL AND (SELECT bs.batter_stat_id FROM BATTER_STATS bs JOIN TEAM_PLAYER tp ON bs.tp_id = tp.tp_id JOIN PLAYER p ON tp.player_id = p.player_id WHERE p.player_name = '박한열' AND tp.team_id = @team_24 AND bs.season_id = @season_id LIMIT 1) IS NOT NULL;
