INSERT INTO BATTER_STATS (tp_id, season_id) SELECT tp.tp_id, @season_id FROM TEAM_PLAYER tp JOIN PLAYER p ON tp.player_id = p.player_id WHERE p.player_name = '김형수' AND tp.team_id = @team_19 AND tp.season_id = @season_id AND NOT EXISTS (SELECT 1 FROM BATTER_STATS bs WHERE bs.tp_id = tp.tp_id AND bs.season_id = @season_id) LIMIT 1;
